%dw 2.0
output application/json
---
{
  fullName: payload.firstName ++ " " ++ payload.lastName
}

%dw 2.0
output application/json
var d = payload.date as Date {format: "dd-MM-yyyy"}
---
{
  iso: d as String {format: "yyyy-MM-dd"},
  withMonthName: d as String {format: "dd-MMM-yyyy"},
  year: d.year
}

%dw 2.0
output application/json
---
{
  amount: payload.amount as String {format: "#,###.00"},
  price: payload.price as Number as String {format: "###.00"},
  code: payload.code as String {format: "000"}
}

%dw 2.0
output application/json
---
payload.employees map ((e) -> e ++ {
  salary: (payload.salaries filter ((s) -> s.id == e.id))[0].salary
})

%dw 2.0
output application/xml indent=false, writeDeclaration=false
---
{
  bookstore: {
    book: payload
  }
}

%dw 2.0
output application/xml indent=false, writeDeclaration=false
---
{
  bookstore: {
    (payload map ((item) -> {
      book @(category: item.category): { title: item.title }
    }))
  }
}

%dw 2.0
output application/json
var s = write(payload, "application/json")
---
{
  storedType: typeOf(s),
  name: read(s, "application/json").name
}
